using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();
    private int _nextEnrollmentId = 1;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of numbers, quantities, structures, and spaces." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Understanding the fundamental laws of the universe." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Examination of past events and their impact on civilization." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#.", Credits = 3, Schedule = "Mon/Wed 9:00-10:30 AM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Expert in software engineering with 15 years of teaching experience.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures and algorithm design.", Credits = 4, Schedule = "Tue/Thu 11:00 AM-12:30 PM", DepartmentId = 1, InstructorName = "Dr. Bob Martinez", InstructorBio = "Researcher in algorithm optimization and computational complexity.", IsFeatured = false },
            new() { Id = 3, Title = "Web Development", Description = "Build modern web applications using ASP.NET Core and Blazor.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00-3:00 PM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Expert in software engineering with 15 years of teaching experience.", IsFeatured = true },
            // Mathematics
            new() { Id = 4, Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00-9:00 AM", DepartmentId = 2, InstructorName = "Dr. Carol Williams", InstructorBio = "Published mathematician specializing in analysis.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Description = "Vectors, matrices, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:30-11:00 AM", DepartmentId = 2, InstructorName = "Dr. David Park", InstructorBio = "Focuses on applied mathematics and numerical methods.", IsFeatured = false },
            new() { Id = 6, Title = "Discrete Mathematics", Description = "Logic, sets, combinatorics, and graph theory.", Credits = 3, Schedule = "Mon/Wed 1:00-2:30 PM", DepartmentId = 2, InstructorName = "Dr. Carol Williams", InstructorBio = "Published mathematician specializing in analysis.", IsFeatured = false },
            // Physics
            new() { Id = 7, Title = "Physics I: Mechanics", Description = "Newtonian mechanics, energy, and momentum.", Credits = 4, Schedule = "Tue/Thu 8:00-9:30 AM", DepartmentId = 3, InstructorName = "Dr. Emily Johnson", InstructorBio = "Experimental physicist with work in particle physics.", IsFeatured = true },
            new() { Id = 8, Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations.", Credits = 4, Schedule = "Mon/Wed 10:00-11:30 AM", DepartmentId = 3, InstructorName = "Dr. Frank Lee", InstructorBio = "Theoretical physicist specializing in field theory.", IsFeatured = false },
            new() { Id = 9, Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrodinger equation, and quantum states.", Credits = 3, Schedule = "Tue/Thu 2:00-3:30 PM", DepartmentId = 3, InstructorName = "Dr. Emily Johnson", InstructorBio = "Experimental physicist with work in particle physics.", IsFeatured = false },
            // English
            new() { Id = 10, Title = "Creative Writing", Description = "Develop skills in fiction, poetry, and creative nonfiction.", Credits = 3, Schedule = "Mon/Wed 3:00-4:30 PM", DepartmentId = 4, InstructorName = "Prof. Grace Taylor", InstructorBio = "Award-winning author and writing workshop leader.", IsFeatured = true },
            new() { Id = 11, Title = "American Literature", Description = "Survey of American literary works from colonial times to present.", Credits = 3, Schedule = "Tue/Thu 1:00-2:30 PM", DepartmentId = 4, InstructorName = "Dr. Henry Adams", InstructorBio = "Scholar of 19th and 20th century American literature.", IsFeatured = false },
            new() { Id = 12, Title = "Technical Writing", Description = "Writing for professional and technical audiences.", Credits = 3, Schedule = "Fri 10:00 AM-1:00 PM", DepartmentId = 4, InstructorName = "Prof. Grace Taylor", InstructorBio = "Award-winning author and writing workshop leader.", IsFeatured = false },
            // History
            new() { Id = 13, Title = "World History", Description = "Major events and movements that shaped the modern world.", Credits = 3, Schedule = "Mon/Wed 11:00 AM-12:30 PM", DepartmentId = 5, InstructorName = "Dr. Isabel Rodriguez", InstructorBio = "Historian specializing in global comparative history.", IsFeatured = true },
            new() { Id = 14, Title = "Ancient Civilizations", Description = "Study of early human civilizations and their contributions.", Credits = 3, Schedule = "Tue/Thu 3:00-4:30 PM", DepartmentId = 5, InstructorName = "Dr. James Wright", InstructorBio = "Archaeologist and ancient history researcher.", IsFeatured = false },
            new() { Id = 15, Title = "Modern European History", Description = "Europe from the Renaissance to the present day.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-2:00 PM", DepartmentId = 5, InstructorName = "Dr. Isabel Rodriguez", InstructorBio = "Historian specializing in global comparative history.", IsFeatured = false }
        };

        // Link departments to courses
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses(int? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLowerInvariant();
            query = query.Where(c =>
                c.Title.ToLowerInvariant().Contains(term) ||
                c.Description.ToLowerInvariant().Contains(term) ||
                c.InstructorName.ToLowerInvariant().Contains(term));
        }

        return query.ToList();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _nextEnrollmentId++;
        request.SubmittedAt = DateTime.UtcNow;
        _enrollments.Add(request);
    }
}

