@page "/"

<PageTitle>Home - University Course Catalog</PageTitle>

<h1>Welcome to Contoso University</h1>
<p class="lead">Discover our diverse range of courses and programs designed to help you achieve your academic goals.</p>

<h2>Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mb-4">
    @foreach (var course in featuredCourses)
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Title</h5>
                    <p class="card-text">
                        <span class="badge bg-secondary">@course.Department?.Name</span>
                        <span class="badge bg-primary">@course.Credits Credits</span>
                    </p>
                    <a href="/courses/@course.Id" class="btn btn-outline-primary">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Departments</h2>
<div class="list-group mb-4">
    @foreach (var dept in departments)
    {
        <a href="/courses?department=@dept.Id" class="list-group-item list-group-item-action">
            <strong>@dept.Code</strong> - @dept.Name
        </a>
    }
</div>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    [Inject] public CatalogService CatalogService { get; set; } = default!;

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" class="form-control" placeholder="Search courses..." value="@Search" />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@if (courses.Any())
{
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Title</td>
                        <td>@course.Department?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}
else
{
    <p class="text-muted">No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? Department { get; set; }

    [Inject] public CatalogService CatalogService { get; set; } = default!;

    private List<Course> courses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Department, Search);
    }
}

